import java.util.*;

class Solution {
    public int romanToInt(String s) {
        // 13 种符号：7 个基础 + 6 个减法特例，按值从大到小排
        String[] sym = {"M","CM","D","CD","C","XC","L","XL","X","IX","V","IV","I"};
        int[] val    = {1000,900,500,400,100,90,50,40,10,9,5,4,1};

        int sum = 0;
        int i = 0;
        while (i < s.length()) {
            // 从值最大的符号开始试，找到第一个能匹配当前前缀的就吃下
            for (int k = 0; k < sym.length; k++) {
                if (i + sym[k].length() <= s.length() && s.startsWith(sym[k], i)) {
                    sum += val[k];
                    i += sym[k].length();   // 指针跳过已消费的长度（1 或 2）
                    break;
                }
            }
        }
        return sum;
    }
}

import java.util.*;

class Solution {
    public int romanToInt(String s) {
        Map<Character, Integer> map = new HashMap<>();
        map.put('I', 1);   map.put('V', 5);
        map.put('X', 10);  map.put('L', 50);
        map.put('C', 100); map.put('D', 500);
        map.put('M', 1000);

        int total = 0;
        int n = s.length();
        for (int i = 0; i < n; i++) {
            int cur = map.get(s.charAt(i));
            // 关键判断：当前小于后一位 → 减（减法特例）；否则 → 加
            if (i < n - 1 && cur < map.get(s.charAt(i + 1))) {
                total -= cur;
            } else {
                total += cur;
            }
        }
        return total;
    }
}

class Solution {
    // 用 switch 把字符映射到数值，O(1) 空间、最快
    private int value(char c) {
        switch (c) {
            case 'I': return 1;
            case 'V': return 5;
            case 'X': return 10;
            case 'L': return 50;
            case 'C': return 100;
            case 'D': return 500;
            case 'M': return 1000;
        }
        return 0;
    }

    public int romanToInt(String s) {
        int total = 0;
        int n = s.length();
        for (int i = 0; i < n; i++) {
            int cur = value(s.charAt(i));
            // 当前 < 后一位 → 减；否则 → 加
            if (i < n - 1 && cur < value(s.charAt(i + 1))) {
                total -= cur;
            } else {
                total += cur;
            }
        }
        return total;
    }
}

