class Solution {
    public int removeDuplicates(int[] nums) {
        int n = nums.length;
        if (n == 0) return 0;

        int[] temp = new int[n];
        int k = 0;
        temp[k++] = nums[0]; // 第一个元素一定保留

        for (int i = 1; i < n; i++) {
            if (nums[i] != nums[i - 1]) { // 遇到新值，放入 temp
                temp[k++] = nums[i];
            }
        }

        // 拷回原数组前 k 位
        for (int i = 0; i < k; i++) {
            nums[i] = temp[i];
        }
        return k;
    }
}

class Solution {
    public int removeDuplicates(int[] nums) {
        if (nums.length == 0) return 0;

        int slow = 0; // 指向已去重部分的最后一个位置
        for (int fast = 1; fast < nums.length; fast++) {
            if (nums[fast] != nums[slow]) { // 遇到新元素
                slow++;                    // 写指针右移
                nums[slow] = nums[fast];   // 把新元素写到正确位置
            }
            // 相等时：fast 继续前进，slow 不动
        }
        return slow + 1; // slow 是下标，数量 = 下标 + 1
    }
}

int slow = 0; // 或 slow = -1, 取决于初始条件
for (int fast = 1; fast < n; fast++) { // fast 从 1 或 0 开始
    if (满足保留条件) {
        slow++;
        nums[slow] = nums[fast]; // 或 arr[slow] = arr[fast]
    }
}
return slow + 1;

