// 暴力思路（仅理解，超时风险）
class Solution {
    public int[][] merge(int[][] intervals) {
        List<int[]> res = new ArrayList<>();
        for (int[] itv : intervals) {
            boolean merged = false;
            for (int[] r : res) {
                if (itv[0] <= r[1] && r[0] <= itv[1]) {  // 有重叠
                    r[0] = Math.min(r[0], itv[0]);
                    r[1] = Math.max(r[1], itv[1]);
                    merged = true;
                    break;
                }
            }
            if (!merged) res.add(new int[]{itv[0], itv[1]});
        }
        // 还需多轮直到稳定（这里省略），最坏 O(n²)
        return res.toArray(new int[0][]);
    }
}

// 最优解：排序 + 一次扫描，O(n log n) 时间、O(1) 额外空间（不计返回）
class Solution {
    public int[][] merge(int[][] intervals) {
        Arrays.sort(intervals, (a, b) -> a[0] - b[0]);   // 按起点升序
        List<int[]> res = new ArrayList<>();
        int[] cur = intervals[0].clone();                 // 当前合并区间
        for (int i = 1; i < intervals.length; i++) {
            int[] itv = intervals[i];
            if (itv[0] <= cur[1]) {                       // 重叠（端点相接也算）
                cur[1] = Math.max(cur[1], itv[1]);        // 延伸终点，取 max
            } else {                                      // 不重叠，结算当前
                res.add(cur);
                cur = itv.clone();                        // 开启新区间
            }
        }
        res.add(cur);                                     // 收尾最后一个区间
        return res.toArray(new int[0][]);
    }
}

