// 暴力思路（不推荐，仅说明：字符串原地反复消去，易错且 O(n²)）
class Solution {
    public String simplifyPath(String path) {
        String s = path;
        // 反复消去 "/./" 和 "a/../" 形式，直到稳定
        // 实现复杂、边界多（如 "/../" 在开头、多个连续斜杠），
        // 每次替换都可能要重新扫描整串，最坏 O(n²)，且极易漏边界
        // 故此处略去具体实现，重点看下面的栈解法
        return s;
    }
}

class Solution {
    public String simplifyPath(String path) {
        // 按 '/' 切分；连续斜杠会产生空串，需要过滤
        String[] parts = path.split("/");
        java.util.Deque<String> stack = new java.util.ArrayDeque<>();

        for (String part : parts) {
            if (part.equals("") || part.equals(".")) {
                // 连续斜杠的空串 或 当前目录 ".", 直接跳过
                continue;
            } else if (part.equals("..")) {
                // 回退上一级; 根目录再回退没有意义, 栈空则忽略
                if (!stack.isEmpty()) {
                    stack.pop();
                }
            } else {
                // 普通目录名(包含 "..." 等), 入栈
                stack.push(part);
            }
        }

        // 用单斜杠拼接; 栈底在最后, 需从底向顶
        StringBuilder sb = new StringBuilder();
        if (stack.isEmpty()) {
            return "/"; // 根目录
        }
        for (String dir : stack) { // ArrayDeque 正序迭代即从底到顶
            sb.append("/").append(dir);
        }
        return sb.toString();
    }
}

