class Solution {
    public List<List<Integer>> generate(int numRows) {
        List<List<Integer>> res = new ArrayList<>();
        for (int i = 0; i < numRows; i++) {
            List<Integer> row = new ArrayList<>();
            for (int j = 0; j <= i; j++) {
                row.add((int) combination(i, j));
            }
            res.add(row);
        }
        return res;
    }

    // 组合数 C(n,k)，用递推公式避免溢出
    private long combination(int n, int k) {
        k = Math.min(k, n - k);  // C(n,k) = C(n, n-k)
        long res = 1;
        for (int i = 1; i <= k; i++) {
            res = res * (n - k + i) / i;  // 边乘边除，保证整除
        }
        return res;
    }
}

import java.util.*;

class Solution {
    public List<List<Integer>> generate(int numRows) {
        List<List<Integer>> result = new ArrayList<>();
        for (int i = 0; i < numRows; i++) {
            List<Integer> row = new ArrayList<>();
            for (int j = 0; j <= i; j++) {
                if (j == 0 || j == i) {
                    row.add(1);                        // 首尾固定为 1
                } else {
                    // 中间 = 上一行左上方 + 右上方
                    int val = result.get(i - 1).get(j - 1)
                            + result.get(i - 1).get(j);
                    row.add(val);
                }
            }
            result.add(row);
        }
        return result;
    }
}

