class Solution {
    public int maxProfit(int[] prices) {
        return dfs(0, false, prices);
    }

    // i: 当前第几天; holding: 是否持有股票
    private int dfs(int i, boolean holding, int[] prices) {
        if (i == prices.length) return 0; // 结束，无更多收益
        if (holding) {
            // 继续持有 或 今天卖出
            int keep = dfs(i + 1, true, prices);
            int sell = prices[i] + dfs(i + 1, false, prices);
            return Math.max(keep, sell);
        } else {
            // 继续空仓 或 今天买入
            int skip = dfs(i + 1, false, prices);
            int buy = dfs(i + 1, true, prices) - prices[i];
            return Math.max(skip, buy);
        }
    }
}

class Solution {
    public int maxProfit(int[] prices) {
        int n = prices.length;
        int i = 0, profit = 0;
        while (i < n - 1) {
            // 找谷底：连续下降的最后一个点
            while (i < n - 1 && prices[i] >= prices[i + 1]) i++;
            int valley = prices[i];
            // 找峰顶：连续上升的最后一个点
            while (i < n - 1 && prices[i] <= prices[i + 1]) i++;
            int peak = prices[i];
            profit += peak - valley; // 吃下整段上升
        }
        return profit;
    }
}

class Solution {
    public int maxProfit(int[] prices) {
        int profit = 0;
        for (int i = 1; i < prices.length; i++) {
            if (prices[i] > prices[i - 1]) {
                profit += prices[i] - prices[i - 1]; // 只赚涨的那一天的差价
            }
        }
        return profit;
    }
}

class Solution {
    public int maxProfit(int[] prices) {
        int n = prices.length;
        int hold = -prices[0]; // 持有股票时的最大利润（初始花 prices[0] 买入）
        int cash = 0;          // 不持有股票时的最大利润
        for (int i = 1; i < n; i++) {
            int newHold = Math.max(hold, cash - prices[i]); // 继续持有 或 买入
            int newCash = Math.max(cash, hold + prices[i]); // 继续空仓 或 卖出
            hold = newHold;
            cash = newCash;
        }
        return cash; // 最后一天必定空仓利润最大
    }
}

