public class Solution {
    public boolean hasCycle(ListNode head) {
        Set<ListNode> seen = new HashSet<>();
        while (head != null) {
            if (seen.contains(head)) return true; // 又走到已访问节点 → 有环
            seen.add(head);
            head = head.next;
        }
        return false;
    }
}

public class Solution {
    public boolean hasCycle(ListNode head) {
        if (head == null || head.next == null) return false; // 0 或 1 个节点必无环
        ListNode slow = head;
        ListNode fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;          // 慢 1 步
            fast = fast.next.next;     // 快 2 步
            if (slow == fast) return true; // 相遇 → 有环
        }
        return false; // fast 走到尽头 → 无环
    }
}

