class Solution {
    public String reverseWords(String s) {
        // 按一个或多个空白切分，自动忽略首尾和多重空格产生的空串
        String[] words = s.trim().split("\\s+");
        // 从后往前拼
        StringBuilder sb = new StringBuilder();
        for (int i = words.length - 1; i >= 0; i--) {
            sb.append(words[i]);
            if (i > 0) sb.append(" ");
        }
        return sb.toString();
    }
}

class Solution {
    public String reverseWords(String s) {
        int n = s.length();
        StringBuilder sb = new StringBuilder();
        int i = n - 1;
        while (i >= 0) {
            // 跳过尾部/单词间的空格
            while (i >= 0 && s.charAt(i) == ' ') i--;
            if (i < 0) break;
            int end = i;                 // 单词右端
            while (i >= 0 && s.charAt(i) != ' ') i--; // 左移到单词左端前一个空格
            // 把 [i+1, end] 这段单词正向加入结果
            sb.append(s, i + 1, end + 1).append(" ");
        }
        // 去掉最后一个多余空格
        if (sb.length() > 0) sb.deleteCharAt(sb.length() - 1);
        return sb.toString();
    }
}

class Solution {
    public String reverseWords(String s) {
        char[] a = s.toCharArray();
        int n = a.length;
        // 1) 整体反转
        reverse(a, 0, n - 1);
        // 2) 逐单词反转 + 3) 清空格前移
        int w = 0; // 写指针（紧凑区末尾）
        int i = 0;
        while (i < n) {
            // 跳过空格
            while (i < n && a[i] == ' ') i++;
            if (i == n) break;            // 全是空格
            if (w > 0) a[w++] = ' ';      // 单词间补一个空格（首个单词前不加）
            int start = w;                // 当前单词起点
            while (i < n && a[i] != ' ') a[w++] = a[i++];
            reverse(a, start, w - 1);     // 把这段单词反转回来
        }
        return new String(a, 0, w);       // 只取紧凑部分
    }

    private void reverse(char[] a, int l, int r) {
        while (l < r) {
            char t = a[l]; a[l] = a[r]; a[r] = t;
            l++; r--;
        }
    }
}

