class Solution {
    public boolean isIsomorphic(String s, String t) {
        Map<Character, Character> map = new HashMap<>();
        for (int i = 0; i < s.length(); i++) {
            char a = s.charAt(i), b = t.charAt(i);
            if (!map.containsKey(a)) map.put(a, b);
            else if (map.get(a) != b) return false;
        }
        return true;
    }
}

class Solution {
    public boolean isIsomorphic(String s, String t) {
        int[] mapS = new int[256]; // s 的字符 -> t 的字符(+1)
        int[] mapT = new int[256]; // t 的字符 -> s 的字符(+1)
        for (int i = 0; i < s.length(); i++) {
            char a = s.charAt(i), b = t.charAt(i);
            if (mapS[a] == 0 && mapT[b] == 0) {
                mapS[a] = b + 1;   // 建立双向映射
                mapT[b] = a + 1;
            } else if (mapS[a] != b + 1 || mapT[b] != a + 1) {
                return false;     // 任一边冲突 -> 非双射
            }
        }
        return true;
    }
}

class Solution {
    public boolean isIsomorphic(String s, String t) {
        int[] lastS = new int[256];
        int[] lastT = new int[256];
        for (int i = 0; i < s.length(); i++) {
            char a = s.charAt(i), b = t.charAt(i);
            if (lastS[a] != lastT[b]) return false; // 上次出现位置不同 -> 非同构
            lastS[a] = i + 1;
            lastT[b] = i + 1;
        }
        return true;
    }
}

