// 暴力：每个位置往后看 k 个，O(n*k)
class Solution {
    public boolean containsNearbyDuplicate(int[] nums, int k) {
        for (int i = 0; i < nums.length; i++) {
            for (int j = i + 1; j <= i + k && j < nums.length; j++) {
                if (nums[i] == nums[j]) return true;
            }
        }
        return false;
    }
}

// 优化解：Map 记录最近下标，O(n) 时间、O(min(n,k)) 空间
class Solution {
    public boolean containsNearbyDuplicate(int[] nums, int k) {
        Map<Integer, Integer> last = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            if (last.containsKey(nums[i]) && i - last.get(nums[i]) <= k) {
                return true;
            }
            last.put(nums[i], i);   // 始终保存「最近一次」的位置
        }
        return false;
    }
}

// 最优解：滑动窗口 Set，O(n) 时间、O(k) 空间
class Solution {
    public boolean containsNearbyDuplicate(int[] nums, int k) {
        Set<Integer> window = new HashSet<>();
        for (int i = 0; i < nums.length; i++) {
            if (window.contains(nums[i])) return true;   // 窗口内已有同值，距离必 ≤ k
            window.add(nums[i]);
            if (window.size() > k) {                       // 窗口大小上限 k+1
                window.remove(nums[i - k]);                // 移除最左（下标 i-k）
            }
        }
        return false;
    }
}

