// 暴力思路（不推荐，仅展示「没用有序性」的笨办法）
class Solution {
    public List<String> summaryRanges(int[] nums) {
        Set<Integer> set = new HashSet<>();
        for (int x : nums) set.add(x);
        List<String> res = new ArrayList<>();
        for (int x : nums) {
            if (set.contains(x - 1)) continue;        // 不是某段起点就跳过
            int y = x;
            while (set.contains(y + 1)) y++;           // 向后探测终点
            res.add(x == y ? String.valueOf(x) : x + "->" + y);
        }
        return res;
    }
}

// 最优解：一次扫描，O(n) 时间、O(1) 额外空间（不计输出）
class Solution {
    public List<String> summaryRanges(int[] nums) {
        List<String> res = new ArrayList<>();
        if (nums.length == 0) return res;          // 空数组直接返回
        int start = 0;
        for (int i = 1; i < nums.length; i++) {
            // 断档：nums[i] 不在当前连续段里
            if (nums[i] != nums[i - 1] + 1) {
                res.add(makeRange(nums, start, i - 1));
                start = i;                          // 开启新区间
            }
        }
        res.add(makeRange(nums, start, nums.length - 1));   // 收尾：最后一个区间
        return res;
    }
    private String makeRange(int[] nums, int lo, int hi) {
        return lo == hi ? String.valueOf(nums[lo])
                        : nums[lo] + "->" + nums[hi];
    }
}

