import java.util.*;

class RandomizedSet {
    private List<Integer> list = new ArrayList<>();

    public RandomizedSet() {}

    public boolean insert(int val) {
        if (list.contains(val)) return false; // O(n) 查重
        list.add(val);
        return true;
    }

    public boolean remove(int val) {
        if (!list.contains(val)) return false;
        list.remove(Integer.valueOf(val));     // O(n) 删除（要移动后面所有元素）
        return true;
    }

    public int getRandom() {
        return list.get((int)(Math.random() * list.size())); // O(1) 随机
    }
}

class RandomizedSet {
    private List<Integer> list = new ArrayList<>();
    private Map<Integer, Integer> pos = new HashMap<>();

    public RandomizedSet() {}

    public boolean insert(int val) {
        if (pos.containsKey(val)) return false;
        pos.put(val, list.size());
        list.add(val);
        return true;
    }

    public boolean remove(int val) {
        if (!pos.containsKey(val)) return false;
        int idx = pos.get(val);
        list.remove(idx);                 // 仍然 O(n) 搬移
        pos.remove(val);
        // 注意：被删元素后面的下标都变了，需要逐个更新 —— 这里其实有 bug，略
        return true;
    }

    public int getRandom() {
        return list.get((int)(Math.random() * list.size()));
    }
}

import java.util.*;

class RandomizedSet {
    private List<Integer> list = new ArrayList<>();
    private Map<Integer, Integer> pos = new HashMap<>();
    private Random rand = new Random();

    public RandomizedSet() {}

    public boolean insert(int val) {
        if (pos.containsKey(val)) return false; // 已存在
        pos.put(val, list.size());              // 新元素下标 = 当前长度
        list.add(val);                           // 追加到末尾
        return true;
    }

    public boolean remove(int val) {
        if (!pos.containsKey(val)) return false; // 不存在
        int idx = pos.get(val);                  // val 当前下标
        int last = list.get(list.size() - 1);    // 末尾元素
        list.set(idx, last);                     // 末尾元素填到 idx 位置（覆盖 val）
        pos.put(last, idx);                      // 更新末尾元素的新下标
        list.remove(list.size() - 1);            // 弹出末尾（O(1)）
        pos.remove(val);                         // 删除 val 映射
        return true;
    }

    public int getRandom() {
        return list.get(rand.nextInt(list.size())); // 等概率随机取
    }
}

