class Solution {
    public boolean isSubsequence(String s, String t) {
        int i = 0, j = 0;                       // i 走 s，j 走 t
        while (i < s.length() && j < t.length()) {
            if (s.charAt(i) == t.charAt(j)) {
                i++;                            // 匹配成功，s 指针前进
            }
            j++;                                // t 指针始终前进（无论是否匹配）
        }
        return i == s.length();                 // s 全部匹配完才是子序列
    }
}

class Solution {
    public boolean isSubsequence(String s, String t) {
        int m = t.length();
        // next[pos][c]：在 t 的 pos 位置之后，字符 c 首次出现的下标；不存在为 -1
        int[][] next = new int[m + 1][26];
        Arrays.fill(next[m], -1);              // 末尾之后任何字符都不存在
        for (int pos = m - 1; pos >= 0; pos--) {
            System.arraycopy(next[pos + 1], 0, next[pos], 0, 26); // 继承后一位的答案
            next[pos][t.charAt(pos) - 'a'] = pos;                 // 当前字符出现在 pos
        }
        int p = 0;                             // 当前在 t 中的查找起点
        for (int i = 0; i < s.length(); i++) {
            p = next[p][s.charAt(i) - 'a'];    // 跳到 s[i] 下一次出现的位置
            if (p == -1) return false;         // t 后续没有这个字符了
            p++;                               // 用掉当前位置，从下一个开始找
        }
        return true;
    }
}

